#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> g(n, vector<long long>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> g[i][j];
        }
    }
    long long q;
    cin >> q;
    vector<long long> x(q);
    for (int i = 0; i < q; i++) cin >> x[i];

    for (int k = 0; k < q; k++) {
        int i = 0, j = m - 1;
        bool found = false;
        while (i < n && j >= 0) {
            if (g[i][j] == x[k]) {
                found = true;
                break;
            }
            if (g[i][j] > x[k]) j--;
            else i++;
        }
        cout << (found ? "yes" : "no") << "\n";
    }

    return 0;
}

