import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        long[][] g = new long[(int) n][(int) m];
        for (int i = 0; i < g.length; i++) {
            for (int j = 0; j < g[i].length; j++) {
                g[i][j] = sc.nextLong();
            }
        }
        long q = sc.nextLong();
        long[] x = new long[(int) q];
        for (int i = 0; i < x.length; i++) x[i] = sc.nextLong();

        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < q; k++) {
            int i = 0, j = (int) m - 1;
            boolean found = false;
            while (i < n && j >= 0) {
                if (g[i][j] == x[k]) {
                    found = true;
                    break;
                }
                if (g[i][j] > x[k]) j--;
                else i++;
            }
            sb.append(found ? "yes" : "no").append("\n");
        }
        System.out.print(sb);
    }
}
